            "operator": "equals",
            "value": "yes"
          }
        ]
      },
      "outcome": "review",
      "onUnknown": "ignore"
    }
  ],
  "exceptions": [
    {
      "id": "x-large-high-exposure",
      "description": "O3 directly escalates clear-screening high-country-risk requests above 2000000.00 when financial evidence is available.",
      "when": {
        "op": "all",
        "conditions": [
          {
            "op": "evidence-present",
